                    <Button className="bg-[#00e5ff] text-[#0a1628] hover:bg-[#00e5ff]/80" onClick={() => { alert("Standardized spec saved!"); setViewingClientSpec(null); }}>
                      <Download className="h-4 w-4 mr-2" /> Save Standardized Spec
                    </Button>
